const stageNo=Number(document.body.dataset.stage||1);
const STAGES={1:{name:'STAGE 1：コイン収集',start:70,end:1580,threshold:350,next:'stage2.html',goal:'ステージ1クリア！'},2:{name:'STAGE 2：高難度エリア',start:1580,end:3150,threshold:750,next:'boss.html',goal:'ボス挑戦権を獲得！'},3:{name:'BOSS：象の老武術家',start:3150,end:4180,threshold:0,next:'',goal:'ボス撃破！'}};
const stage=STAGES[stageNo]||STAGES[1];

// オリジナル簡易チップチューンBGMと効果音（外部音源ファイル不要）
const lionAudio=(()=>{
 let ac=null,master=null,musicTimer=null,step=0,enabled=true,started=false;
 const patterns={
  1:[659,784,988,784,587,659,784,659,523,659,784,659,587,523,440,523],
  2:[587,698,784,698,523,587,698,587,466,523,698,587,466,523,587,466],
  3:[440,523,587,659,392,440,523,587,349,392,440,523,330,392,440,494]
 };
 function init(){if(!ac){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;ac=new AC();master=ac.createGain();master.gain.value=.22;master.connect(ac.destination);}if(ac.state==='suspended')ac.resume();return true;}
 function tone(freq,dur=.12,type='square',vol=.12,when=0,slide=0){if(!enabled||!init())return;const t=ac.currentTime+when,o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(Math.max(35,freq),t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(35,freq+slide),t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,vol),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+.02);}
 function chord(notes,dur=.2,type='triangle',vol=.045){notes.forEach((n,i)=>tone(n,dur,type,vol,0,0));}
 function musicStep(){if(!enabled||!started||!ac||ac.state!=='running')return;const p=patterns[stageNo]||patterns[1],n=p[step%p.length];tone(n,.145,'square',.055);if(step%4===0)tone(n/2,.19,'triangle',.035);if(stageNo===3&&step%8===4)tone(n*1.5,.11,'sawtooth',.022);step++;}
 function startMusic(){if(!init())return;started=true;if(musicTimer)clearInterval(musicTimer);step=0;musicStep();musicTimer=setInterval(musicStep,175);}
 function stopMusic(){started=false;if(musicTimer)clearInterval(musicTimer);musicTimer=null;}
 function toggle(){enabled=!enabled;const b=document.getElementById('lionSoundButton');if(!enabled){stopMusic();if(master&&ac)master.gain.setTargetAtTime(0,ac.currentTime,.03);}else{if(init())master.gain.setTargetAtTime(.22,ac.currentTime,.04);if(active)startMusic();}if(b)b.textContent=enabled?'🔊 音 ON':'🔇 音 OFF';}
 function sfx(name){if(!enabled)return;switch(name){case'coin':chord([988,1318],.09,'square',.065);tone(1568,.11,'triangle',.045,.06);break;case'jump':tone(330,.12,'square',.06,0,260);break;case'good':chord([523,659,784],.18,'triangle',.055);tone(1047,.2,'square',.045,.13);break;case'bad':tone(420,.18,'sawtooth',.06,0,-230);tone(190,.2,'triangle',.06,.1,-60);break;case'damage':tone(210,.24,'sawtooth',.09,0,-130);tone(95,.22,'square',.055,.04,-35);break;case'special':chord([220,330,440],.28,'sawtooth',.055);tone(880,.22,'square',.08,.12,500);break;case'bossHit':chord([150,220,300],.22,'sawtooth',.075);break;case'bossDown':[523,659,784,1047].forEach((n,i)=>tone(n,.25,'square',.07,i*.13));break;case'spring':tone(280,.16,'triangle',.065,0,600);break;case'magma':tone(120,.28,'sawtooth',.065,0,240);break;case'spikeWarn':tone(260,.13,'square',.055);tone(190,.16,'square',.05,.16,-50);break;case'spikeRise':tone(95,.22,'sawtooth',.08,0,180);tone(180,.12,'square',.045,.08,80);break;case'clear':[659,784,988,1318].forEach((n,i)=>tone(n,.22,'triangle',.06,i*.12));break;}}
 function addButton(){if(document.getElementById('lionSoundButton'))return;const b=document.createElement('button');b.id='lionSoundButton';b.type='button';b.textContent='🔊 音 ON';b.title='BGM・効果音のON/OFF';b.style.cssText='position:fixed;top:12px;right:12px;z-index:10000;padding:9px 12px;border:2px solid #fff;border-radius:12px;background:#172b49;color:#fff;font:bold 14px system-ui;box-shadow:0 2px 8px #0004;touch-action:manipulation';b.addEventListener('click',()=>{init();toggle();});document.body.appendChild(b);}
 addEventListener('pointerdown',()=>{if(enabled&&active&&!started)startMusic();},{once:true});
 addEventListener('visibilitychange',()=>{if(document.hidden)stopMusic();else if(enabled&&active)startMusic();});
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',addButton);else addButton();
 return {startMusic,stopMusic,sfx,toggle};
})();
function readCarry(){try{return Number(localStorage.getItem('shakureLionCarryScore')||0)||0;}catch(e){return 0;}}
function saveCarry(v){try{localStorage.setItem('shakureLionCarryScore',String(v));}catch(e){}}
const RETRY_PENALTY=100;
function readRetryPenalty(){try{return Math.max(0,Number(localStorage.getItem('shakureLionRetryPenalty')||0)||0);}catch(e){return 0;}}
function addRetryPenalty(){try{localStorage.setItem('shakureLionRetryPenalty',String(readRetryPenalty()+RETRY_PENALTY));}catch(e){}}
function clearRetryPenalty(){try{localStorage.removeItem('shakureLionRetryPenalty');}catch(e){}}
function readChinCarry(){try{return Math.max(0,Math.min(8,Number(localStorage.getItem('shakureLionCarryChin')||0)||0));}catch(e){return 0;}}
function saveChinCarry(v){try{localStorage.setItem('shakureLionCarryChin',String(Math.max(0,Math.min(8,v))));}catch(e){}}

